    if re.match(r'^\d{4}-\d{2}-\d{2}$', tarih_str):
        try:
            datetime.strptime(tarih_str, '%Y-%m-%d')
            return tarih_str[:7]
        except:
            return None

    # YYYY/MM/DD
    if re.match(r'^\d{4}/\d{2}/\d{2}$', tarih_str):
        try:
            datetime.strptime(tarih_str, '%Y/%m/%d')
            return tarih_str[:7]
        except:
            return None

    # GG.AA.YYYY (05.03.2025)
    if re.match(r'^\d{2}\.\d{2}\.\d{4}$', tarih_str):
        try:
            datetime.strptime(tarih_str, '%d.%m.%Y')
            return tarih_str[:7]
        except:
            return None

    # G Ay YYYY (2 Nisan 2025)
    months = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
    match = re.match(r'^(\d+)\s+([A-Za-z]+)\s+(\d{4})$', tarih_str)
    if match:
        g = int(match.group(1))
        ay = match.group(2).capitalize()
        yy = int(match.group(3))
        if ay in months and 1 <= g <= 31:
            try:
                m = months.index(ay) + 1
                datetime.strptime(f"{yy}-{m:02d}-{g:02d}", '%Y-%m-%d')
                return f"{yy}-{m:02d}"
            except:
                pass

    return None

